document.addEventListener("DOMContentLoaded",function(){const faqQuestions=document.querySelectorAll(".faq-question");faqQuestions.forEach((question)=>{question.addEventListener("click",function(){const openAnswer=document.querySelector(".faq-answer.open");const openQuestion=document.querySelector(".faq-question.open");if(openAnswer&&openAnswer!==this.nextElementSibling){openAnswer.classList.remove("open");openQuestion.classList.remove("open")}
const answer=this.nextElementSibling;if(answer.classList.contains("open")){answer.classList.remove("open");this.classList.remove("open")}else{answer.classList.add("open");this.classList.add("open")}})})})